import {WALK_SPEED} from './movement.mjs';
const INTENSITIES=[1,.55,.3];
export function installWalkValidation({world,state,motion,setInspect,resetJoy}){
 const hud=document.createElement('section');hud.id='walkValidation';hud.style.cssText='position:fixed;left:14px;top:104px;width:205px;z-index:42;padding:11px;background:#142b3cef;border:1px solid #ffffff35;border-radius:7px;color:#f6f4eb;font:10px Barlow,Arial,sans-serif;line-height:1.6;touch-action:auto';
 const $=s=>document.querySelector(s);
 hud.innerHTML='<b style="color:#ffb369;letter-spacing:1px">VALIDACIÓN · HOTFIX 001 / 002</b><div id="testStatus">Quieto → 4 m → giro → 4 m.<br>Intensidades: 100%, 55% y 30%.</div><button id="runWalkTest" style="background:#ff9037;color:#142b3c;padding:8px 10px;border-radius:4px;margin-top:8px;font-weight:700">Iniciar y grabar prueba</button><a id="downloadWalkVideo" hidden style="display:none;color:#69dfc8;margin-top:8px" download="DrillRun_Hotfix_001_002_Caminata.webm">Descargar video de la caminata</a>';
 document.body.append(hud);const status=hud.querySelector('#testStatus'),button=hud.querySelector('button'),download=hud.querySelector('a');$('#objective')?.classList.add('hidden');
 let active=false,round=0,stage='idle',elapsed=0,results=[],startZ=7.6,recording=null,chunks=[],frames=0,started=0,recordedURL=null;
 const states={idle:'Quieto · 2 segundos',out:'Caminando 4 m',stop:'Detención completa',turn:'Giro de 180°',back:'Regreso de 4 m',finish:'Fin de recorrido',turnNext:'Preparando siguiente intensidad'};
 function begin(){world.lockValidationCamera=true;setInspect(false);resetJoy();state.position={x:.15,z:startZ};motion.vx=motion.vz=0;motion.yaw=Math.PI;world.player.rotation.y=Math.PI;world.worker.reset();$('#objective')?.classList.add('hidden');world.playerGround=world.sampleGround(.15,startZ);results=[];round=0;stage='idle';elapsed=0;active=true;frames=0;started=performance.now();chunks=[];button.disabled=true;button.textContent='Prueba en curso…';download.hidden=true;download.style.display='none';try{const canvas=world.renderer.domElement;const stream=canvas.captureStream(15),options={mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm',videoBitsPerSecond:2200000};recording=new MediaRecorder(stream,options);recording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recording.onstop=()=>{if(recordedURL)URL.revokeObjectURL(recordedURL);recordedURL=URL.createObjectURL(new Blob(chunks,{type:'video/webm'}));download.href=recordedURL;download.hidden=false;download.style.display='block';stream.getTracks().forEach(t=>t.stop());};recording.start(1000);}catch{recording=null;}}
 function next(s){stage=s;elapsed=0;}
 function end(){world.lockValidationCamera=false;active=false;button.disabled=false;button.textContent='Repetir prueba';if(recording?.state==='recording')recording.stop();const metrics=results.reduce((sum,r)=>({distance:sum.distance+r.metrics.distance,steps:sum.steps+r.metrics.steps,maxContactError:Math.max(sum.maxContactError,r.metrics.maxContactError),clampedFrames:sum.clampedFrames+r.metrics.clampedFrames}),{distance:0,steps:0,maxContactError:0,clampedFrames:0});const data={results,metrics,model:world.worker.stats,meanFramesPerSecond:frames/((performance.now()-started)/1000),renderer:world.renderer.isSoftwareRenderer?'Canvas 2D compatible':'WebGL2',note:'La prueba utiliza el mismo controlador y el mismo personaje de la escena jugable.'};const body=JSON.stringify(data,null,2);let report=$('#walkTestReport');if(!report){report=document.createElement('pre');report.id='walkTestReport';report.style.cssText='white-space:pre-wrap;font-size:8px;max-height:110px;overflow:auto';const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Ver mediciones';details.append(summary,report);hud.append(details);}report.textContent=body;status.innerHTML='<b style="color:#69dfc8">Prueba terminada</b><br>'+results.map(r=>`${Math.round(r.intensity*100)}% · ${r.outbound.toFixed(2)} m / ${r.returned.toFixed(2)} m`).join('<br>')+`<br>Apoyo IK: ${(metrics.maxContactError*1000).toFixed(1)} mm de error máximo.`;}
 function input(dt){if(!active)return null;elapsed+=dt;frames++;const intensity=INTENSITIES[round];let z=0;
  if(stage==='idle'){if(elapsed>=2)next('out');}
  else if(stage==='out'){const remaining=state.position.z-(startZ-4);z=-Math.min(intensity,Math.max(0,remaining)*5/WALK_SPEED);if(remaining<.008&&motion.speed<.035){results.push({intensity,outbound:startZ-state.position.z,returned:0});next('stop');}}
  else if(stage==='stop'){if(elapsed>=.9)next('turn');}
  else if(stage==='turn'){z=.04;if(elapsed>=1.1)next('back');}
  else if(stage==='back'){const remaining=startZ-state.position.z;z=Math.min(intensity,Math.max(0,remaining)*5/WALK_SPEED);if(remaining<.008&&motion.speed<.035){results.at(-1).returned=state.position.z-(startZ-4);results.at(-1).metrics={...world.worker.metrics};next('finish');}}
  else if(stage==='finish'){if(elapsed>=.9){round++;if(round>=INTENSITIES.length){end();return{x:0,z:0};}next('turnNext');}}
  else if(stage==='turnNext'){z=-.04;if(elapsed>=1.1){world.worker.reset();next('idle');}}
  if(frames%6===0)status.textContent=`${states[stage]} · ${Math.round(intensity*100)}%\nVelocidad: ${motion.speed.toFixed(2)} m/s\nIda: ${(startZ-state.position.z).toFixed(2)} m · ronda ${round+1}/3\n${(frames/((performance.now()-started)/1000)).toFixed(1)} actualizaciones/s en este navegador`;status.style.whiteSpace='pre-line';return {x:0,z};
 }
 button.onclick=begin;if(new URLSearchParams(location.search).get('walktest')==='auto')setTimeout(begin,600);
 return {input,get active(){return active;}};
}
